<script setup lang="ts">
import{onMounted,ref,computed}from'vue';import{useRoute}from'vue-router';import{vendorAPI,getApiErrorMessage}from'../../services/api';import type{VendorOrderShare}from'../../services/api';import StatusBadge from'../../components/StatusBadge.vue';import OrderProgress from'../../components/OrderProgress.vue';import ConfirmDialog from'../../components/ConfirmDialog.vue';
const route=useRoute(),share=ref<VendorOrderShare|null>(null),loading=ref(true),acting=ref(false),error=ref(''),confirmOpen=ref(false);const action=computed(()=>share.value?.status==='pending'?'confirmed':share.value?.status==='confirmed'?'shipped':null);const actionLabel=computed(()=>action.value==='confirmed'?'Confirm order':action.value==='shipped'?'Mark as sent to Kisaku store':'');
async function load(){loading.value=true;error.value='';try{share.value=await vendorAPI.getOrder(Number(route.params.id))}catch(e:unknown){error.value=getApiErrorMessage(e,'Order could not be loaded.')}finally{loading.value=false}}async function run(){if(!share.value||!action.value)return;acting.value=true;error.value='';try{share.value=await vendorAPI.updateOrderStatus(share.value.order_id,action.value);await load()}catch(e:unknown){error.value=getApiErrorMessage(e,'Status could not be updated.');if([409].includes((e as any)?.response?.status))await load()}finally{acting.value=false;confirmOpen.value=false}}onMounted(load)
</script><template><main class="vendor-main"><router-link class="back" to="/vendor/orders">&larr; Back to orders</router-link><div v-if="loading" class="state">Loading order...</div><div v-else-if="error" class="alert">{{error}}</div><template v-if="share&&!loading"><header class="order-head"><div><p>ORDER</p><h1>{{share.order_number}}</h1></div><StatusBadge :status="share.status"/></header><section class="panel"><h2>Order progress</h2><OrderProgress :status="share.status" :timestamps="{placed_at:share.placed_at,confirmed_at:share.confirmed_at,shipped_at:share.shipped_at,received_at:share.received_at}"/></section><section class="panel"><h2>Items</h2><div class="items"><div v-for="item in share.items" :key="item.product_id" class="item"><img v-if="item.image" :src="item.image" alt=""/><div><strong>{{item.name}}</strong><small>{{item.quantity}} x KSh {{item.unit_price.toLocaleString()}}</small></div><b>KSh {{item.line_total.toLocaleString()}}</b></div></div><footer class="subtotal"><span>Subtotal</span><strong>KSh {{share.subtotal.toLocaleString()}}</strong></footer></section><div v-if="share.status==='cancelled'" class="cancelled">This order was cancelled. Please do not send these goods.</div><div v-else-if="share.status==='shipped'" class="waiting">Waiting for the store to receive your goods</div><div v-else-if="share.status==='received'" class="received">Received by Kisaku</div><div v-else-if="share.status==='pending'&&!share.payment_cleared" class="waiting">Waiting for the customer's payment. You can confirm once it is paid.</div><button v-if="action&&share.payment_cleared" type="button" class="action" :disabled="acting" @click="confirmOpen=true">{{actionLabel}}</button><p class="send-note">Send the goods to the Kisaku store. We deliver to the customer.</p></template><ConfirmDialog :open="confirmOpen" :title="action==='confirmed'?'Confirm this order?':'Send goods to Kisaku?'" :message="action==='confirmed'?'You are saying you will supply these items.':'Confirm that these goods have been sent to the Kisaku store.'" :confirm-text="action==='confirmed'?'Confirm order':'Mark as sent'" :loading="acting" @close="confirmOpen=false" @confirm="run"/></main></template><style scoped>.vendor-main{padding:18px 28px}.back{display:inline-block;margin-bottom:14px;color:#075397;text-decoration:none}.state,.alert{padding:16px;border-radius:7px;background:#fff}.alert{margin-bottom:12px;background:#feeaea;color:#b42318}.order-head{display:flex;justify-content:space-between;align-items:center}.order-head p{margin:0;color:#075397;font-size:.66rem;font-weight:800}.order-head h1{margin:4px 0 16px}.panel{margin-bottom:14px;padding:18px;border:1px solid #e6ebf1;border-radius:8px;background:#fff}.panel h2{margin:0 0 18px;font-size:1rem}.items{display:flex;flex-direction:column}.item{display:grid;grid-template-columns:52px 1fr auto;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #edf0f3}.item img{width:52px;height:52px;border-radius:6px;object-fit:cover}.item div{display:flex;flex-direction:column}.item small{color:#64748b}.subtotal{display:flex;justify-content:flex-end;gap:30px;padding-top:14px}.waiting,.received,.cancelled{margin:12px 0;padding:11px;border-radius:6px}.waiting{background:#fff3df;color:#8a5700}.received{background:#e8f7ef;color:#18794e}.cancelled{background:#feeaea;color:#b42318}.action{height:44px;padding:0 16px;border:0;border-radius:6px;background:#ff7900;color:#fff;font-weight:800}.send-note{margin-top:12px;color:#526579;font-size:.78rem}@media(max-width:700px){.vendor-main{padding:14px}.panel{padding:14px}.item{grid-template-columns:48px 1fr auto}}</style>